SELECT CASE WHEN (CASE WHEN (SELECT 1 FROM LATERAL (SELECT "U0"."ID" AS "ID" FROM "TESTAPP_AUTHOR" "U0" WHERE "U0"."NAME" = %s) AS "DJDB2I_IN" (V1) WHERE "DJDB2I_IN".V1 = "TESTAPP_BOOK"."AUTHOR_ID" FETCH FIRST 1 ROWS ONLY) IS NOT NULL THEN TRUE WHEN (SELECT 1 FROM LATERAL (SELECT "U0"."ID" AS "ID" FROM "TESTAPP_AUTHOR" "U0" WHERE "U0"."NAME" = %s) AS "DJDB2I_IN" (V1) WHERE ("DJDB2I_IN".V1 = "TESTAPP_BOOK"."AUTHOR_ID" OR "DJDB2I_IN".V1 IS NULL OR "TESTAPP_BOOK"."AUTHOR_ID" IS NULL) FETCH FIRST 1 ROWS ONLY) IS NOT NULL THEN NULL ELSE FALSE END) = TRUE THEN TRUE ELSE FALSE END AS "B" FROM "TESTAPP_BOOK";
